export const source="let fillCalls:number=0;class Canvas { color:()=>number; paint:(image:Image)=>void; constructor(){this.color=()=>{fillCalls+=1;return 2};this.paint=(image:Image)=>{image.fill(this.color());image.fillRect(-1,1,3,2,5)}} }\nlet fillImage=image.create(3,3);let painter=new Canvas();painter.paint(fillImage);let fillTop:number=fillImage.getPixel(0,0);let fillLeft:number=fillImage.getPixel(0,1);let fillBottom:number=fillImage.getPixel(1,2);let fillRight:number=fillImage.getPixel(2,1);";
